using System.Diagnostics;
using System.Text.Json;
namespace ONEXTweaks.WidgetBridge;
internal static class ControllerDs4CaptureVerification
{
 private sealed class Samples:IControllerGyroStream{internal bool Enabled,Disposed;public void Configure(bool value){Enabled=value;}public ControllerGyroReading Read()=>new(Enabled,new(0,-90,0),new(0,0,-1),0,0,1);public ValueTask DisposeAsync(){Enabled=false;Disposed=true;return ValueTask.CompletedTask;}}
 internal static async Task<int> Hold(string ready){
  string reports=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ONEXTweaks","dev","Reports");ControllerOutputDevice? output=null;await using var runtime=new ControllerRemapper(reports,outputFactory:(source,vibration)=>output=new(source,vibration,"DualShock4"));await runtime.Start();
  string temp=ready+".tmp";await File.WriteAllTextAsync(temp,JsonSerializer.Serialize(new{pid=Environment.ProcessId,serial=output!.Serial},Backend.Program.Json));File.Move(temp,ready,true);while(runtime.Read().Running)await Task.Delay(100);return 3;
 }
 internal static async Task<int> Native(string file){
  int checks=0;bool xboxCapture=false,ds4Capture=false,ownOutput=false,crash=false,recoveryTest=false;string? error=null;string reports=Path.GetDirectoryName(file)!,leaseFile=ControllerCaptureLease.LeaseFile(reports);ControllerRemapper? runtime=null;ControllerDs4HidReader? hid=null;Process? worker=null,watchdog=null;string? ready=null,crashSerial=null;
  ControllerHideState before;using(var hide=new ControllerHidHide())before=hide.Read();var original=ControllerNative.Slots();void Check(bool ok,string why){checks++;if(!ok)throw new IOException(why);}
  try{
   Check(original.SequenceEqual(new[]{0})&&ControllerNative.Read(0,out var frame)&&ControllerNative.Neutral(frame)&&!File.Exists(leaseFile),"Protect owner's active input/capture");using var window=new ControllerTestWindow();window.RequireForeground();
   // Default output uses the same accepted Xbox class, now through the common owner wrapper.
   var xboxSamples=new Samples();runtime=new ControllerRemapper(reports,gyroFactory:()=>xboxSamples);runtime.Policy(new(Gyro:new("RightStick","Always")));await runtime.Start();Check(runtime.Read().Running&&runtime.Read().OutputTarget=="Xbox360"&&runtime.Read().VirtualSlot>=0,"Default Xbox capture changed");xboxCapture=true;
   bool seen=false;for(int n=0;n<160;n++){if(ControllerNative.Read(runtime.Read().VirtualSlot,out var value)&&ControllerNative.Read(0,out var source)&&value.Rx==Math.Clamp(source.Rx+16384,-32768,32767)){seen=true;break;}await Task.Delay(10);}Check(seen,"Default Xbox wrapper lost actual output");await runtime.Stop();Check(xboxSamples.Disposed&&!File.Exists(leaseFile)&&(await ControllerRemapper.Observe(reports)).SequenceEqual(original),"Default Xbox stop did not restore physical input");await runtime.DisposeAsync();runtime=null;
   ControllerOutputDevice? output=null;var samples=new Samples();window.RequireForeground();runtime=new ControllerRemapper(reports,gyroFactory:()=>samples,outputFactory:(source,vibration)=>output=new(source,vibration,"DualShock4"));runtime.Policy(new(Gyro:new("RightStick","Always")));await runtime.Start();var live=runtime.Read();Check(live.Running&&live.OutputTarget=="DualShock4"&&live.VirtualSlot==-1&&live.ObserverVirtualSlot==-1,"DS4 capture did not establish HID mode");ds4Capture=true;
   Check((await ControllerRemapper.Observe(reports)).Length==0,"Independent client still sees hidden physical XInput");Check(ControllerNative.Read(0,out _),"Whitelisted source reader lost physical input");hid=await ControllerDs4HidReader.OpenOwned(output!.Serial!);await hid.ReadUntil(b=>b[3]==192);Check(runtime.Read().Gyro?.Active==true,"Production DS4 loop did not translate synthetic gyro input into actual HID RX");ownOutput=true;
   runtime.Policy(new());await hid.ReadUntil(b=>b[3]==128);Check(!samples.Enabled,"DS4 policy change left old output active");await Task.Delay(1800);Check(runtime.Read().Running&&File.Exists(leaseFile),"DS4 steady capture/lease stopped");string serial=output.Serial!;hid.Dispose();hid=null;await runtime.Stop();Check(samples.Disposed&&!File.Exists(leaseFile),"DS4 normal stop did not release its sensor/lease");Check(!await ControllerDs4HidReader.IsOwnedPresent(serial),"DS4 normal stop left its HID output");Check((await ControllerRemapper.Observe(reports)).SequenceEqual(original),"DS4 normal stop did not restore physical XInput");await runtime.DisposeAsync();runtime=null;
   // Existing least-privilege installed recovery must work without this new helper or its watchdog.
   window.RequireForeground();ready=Path.Combine(reports,"..","privateReports","ds4-capture334-ready-"+Guid.NewGuid().ToString("N")+".json");var start=new ProcessStartInfo(Environment.ProcessPath!){UseShellExecute=false,CreateNoWindow=true};start.ArgumentList.Add("--controller-ds4-capture-worker");start.ArgumentList.Add(ready);worker=Process.Start(start)??throw new IOException("Own DS4 recovery worker did not start");
   for(int n=0;n<200&&!File.Exists(ready);n++){if(worker.HasExited)throw new IOException("Own DS4 recovery worker failed before ready");await Task.Delay(50);}Check(File.Exists(ready),"Own DS4 recovery worker did not signal ready");using(var json=JsonDocument.Parse(await File.ReadAllTextAsync(ready))){Check(json.RootElement.GetProperty("pid").GetInt32()==worker.Id,"Own worker identity mismatch");crashSerial=json.RootElement.GetProperty("serial").GetString();}
   var lease=JsonSerializer.Deserialize<ControllerLeaseData>(await File.ReadAllTextAsync(leaseFile),Backend.Program.Json)??throw new IOException("Own DS4 recovery lease missing");Check(lease.Pid==worker.Id&&lease.WatchdogPid>0,"DS4 lease identity not recorded");watchdog=Process.GetProcessById(lease.WatchdogPid);Check(watchdog.StartTime.ToUniversalTime().Ticks==lease.WatchdogStartedUtcTicks&&string.Equals(watchdog.MainModule?.FileName,Environment.ProcessPath,StringComparison.OrdinalIgnoreCase),"Do not stop a foreign monitor");
   watchdog.Kill();await watchdog.WaitForExitAsync();worker.Kill();await worker.WaitForExitAsync();crash=true;DateTime stamp=await ControllerLoginRecovery.RunForVerification();string recoveryFile=Path.Combine(reports,"controller-login-recovery.json");using(var json=JsonDocument.Parse(await File.ReadAllTextAsync(recoveryFile)))Check(File.GetLastWriteTimeUtc(recoveryFile)>=stamp&&json.RootElement.GetProperty("result").GetString()=="stale-input-restored","Installed independent recovery did not restore stopped DS4 capture");recoveryTest=true;
   Check(!File.Exists(leaseFile)&&(await ControllerRemapper.Observe(reports)).SequenceEqual(original),"Physical input did not return after DS4 owner+watchdog failure");bool present=true;for(int n=0;n<150;n++){present=await ControllerDs4HidReader.IsOwnedPresent(crashSerial!);if(!present)break;await Task.Delay(50);}Check(!present,"DS4 HID endpoint survived server process failure");
  }catch(Exception e){error=e.Message.Replace(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"<user>",StringComparison.OrdinalIgnoreCase);}
  finally{
   hid?.Dispose();if(runtime!=null)try{await runtime.DisposeAsync();}catch(Exception e){error=(error??"")+"; "+e.Message;}
   foreach(var process in new[]{worker,watchdog})if(process!=null){try{if(!process.HasExited)process.Kill();await process.WaitForExitAsync();}catch{}process.Dispose();}
   try{await ControllerCaptureLease.RecoverStopped(reports);}catch(Exception e){error=(error??"")+"; "+e.Message;}
   if(ready!=null)foreach(string path in new[]{ready,ready+".tmp"})if(File.Exists(path))File.Delete(path);
   ControllerHideState after;using(var hide=new ControllerHidHide())after=hide.Read();bool restored=before.Active==after.Active&&before.Inverse==after.Inverse&&before.Devices.SequenceEqual(after.Devices)&&before.Applications.SequenceEqual(after.Applications);
   await File.WriteAllTextAsync(file,JsonSerializer.Serialize(new{passed=error==null&&restored,checks,error,hidHideConfigurationRestored=restored,actualDefaultXboxCapture=xboxCapture,actualDs4Capture=ds4Capture,actualOwnHidOutput=ownOutput,syntheticGyroInput=ownOutput,ownerAndWatchdogCrashTested=crash,installedIndependentRecoveryTested=recoveryTest,ownerPreferencesWritten=false,physicalOwnerInputTested=false,ds4ExposedInUserInterface=false},Backend.Program.Json));
  }
  using var result=JsonDocument.Parse(await File.ReadAllTextAsync(file));return result.RootElement.GetProperty("passed").GetBoolean()?0:2;
 }
}
